          // Disable marker (hum GPS marker use kar rahe hain)
          circlemarker: false // Disable circle marker
        }
      });
      map.addControl(drawControl);

      // 3. Jab koi shape create ho, toh use 'drawnItems' group mein add karein
      // CHANGED: apply usage color to created layers
      map.on(L.Draw.Event.CREATED, function (event) {
        const layer = event.layer;
        const usage = usageRef.current; // read current usage selection
