      accuracy: capturedLocation.accuracy,
      kmlData: kmlString
    };
    delete surveyData.photos;
    console.log('Data to be sent to MongoDB:', surveyData);

    // CHANGED: create a colored marker for the saved survey based on usage
    const usageColor = getUsageColor(formData.usageOfProperty);
