    let kml = tokml(filtered);

    // ---------------------------
    // CHANGED: compute usage-based colors for KML style (instead of fixed blue)
    // ---------------------------
    const usage = usageRef.current || 'Residential';
    const hex = (USAGE_COLORS[usage] || USAGE_COLORS['Residential']).toUpperCase(); // e.g. "4F46E5"
    const strokeKml = hexToKmlColor(hex, 'FF'); // solid stroke
    const fillKml = hexToKmlColor(hex, '33'); // light fill

