import { useState, useEffect, useRef, useCallback } from 'react';
// --- NAYA IMPORT (Download icon ke liye) ---
import { MapPin, Navigation, Loader, Crosshair, CheckSquare, Download } from 'lucide-react';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
// --- NAYE IMPORTS (Leaflet-Draw ke liye) ---
import 'leaflet-draw/dist/leaflet.draw.css';
import 'leaflet-draw';
import tokml from 'tokml'; // KML export ke liye

import '../Style/map.css';
import HouseDetailsModal from './HouseDetailsModal';

/**
 * KML string ko file ke roop mein download karata hai.
 * @param {string} kmlString - Poora KML content.
 * @param {string} fileName - File ka naam (e.g., "house-123.kml").
 */
const downloadKML = (kmlString, fileName) => {
  const blob = new Blob([kmlString], { type: 'application/vnd.google-earth.kml+xml' });
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = fileName;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(link.href);
};

// ---------------------------
// NEW: Usage color utilities & map helpers
// ---------------------------
// usage -> hex color (6-digit, no #)
const USAGE_COLORS = {
  Residential: '4F46E5',
  Commercial:  '0EA5A4',
  Industrial:  'DC2626',
  Institutional:'F59E0B',
  Government:  '0EA5F7',
  Hospital:    'EF4444',
  'Community Hall':'8B5CF6',
  'Entertainment Hall':'DB2777',
  'Without CC': '374151',
  'Change of properties':'059669',
  'Unauthorized towers':'F97316'
};

function getUsageColor(usage) {
  if (!usage) return '#4F46E5';
  return '#' + (USAGE_COLORS[usage] || USAGE_COLORS['Residential']);
}

function createColoredDivIcon(color, size = 18) {
  const html = `<div style="
      width:${size}px;
      height:${size}px;
      border-radius:50%;
      background:${color};
      box-shadow: 0 0 0 4px rgba(0,0,0,0.06), 0 0 8px rgba(0,0,0,0.12);
      border: 2px solid white;
      display:block;
  "></div>`;
  return L.divIcon({
    html,
    className: '',
    iconSize: [size, size],
    iconAnchor: [size/2, size/2]
  });
}

// convert RRGGBB hex (no #) to KML AABBGGRR (alpha + B G R)
function hexToKmlColor(hexColor, alphaHex = '80') {
  const r = hexColor.slice(0,2);
  const g = hexColor.slice(2,4);
  const b = hexColor.slice(4,6);
  return `${alphaHex}${b}${g}${r}`;
}
